    async def create(
        self,
        *,
        billing_period_end: typing.Optional[dt.datetime] = OMIT,
        billing_period_start: typing.Optional[dt.datetime] = OMIT,
        currency: typing.Optional[str] = OMIT,
        customer_id: typing.Optional[str] = OMIT,
        description: typing.Optional[str] = OMIT,
        issue_date: typing.Optional[dt.datetime] = OMIT,
        line_items: typing.Optional[typing.Sequence[CreateInvoiceLineItemRequest]] = OMIT,
        merchant_id: typing.Optional[str] = OMIT,
        payment: typing.Optional[InvoicePaymentRequest] = OMIT,
        purchase_order_number: typing.Optional[str] = OMIT,
        status: typing.Optional[CreateInvoiceRequestStatus] = OMIT,
        tax_calculation_id: typing.Optional[str] = OMIT,
        idempotency_key: typing.Optional[str] = None,
        request_options: typing.Optional[RequestOptions] = None,
    ) -> InvoiceResponse:
        """
        Creates an ad-hoc invoice for a customer. Callers can supply line items, a billing period, purchase order number, and an initial status (`draft` or `issued`). Requesting `issued` releases the invoice for issuance, which completes asynchronously — the response returns the invoice in `processing` and it settles to `issued` shortly after, observable via the Get Invoice endpoint. Alternatively, pass `tax_calculation_id` to turn a persisted tax calculation into an invoice: its line items, tax, and buyer are pinned and the invoice is issued synchronously; add a `payment` and `status: paid` to record settlement and mark it paid in the same call.

        Parameters
        ----------
        billing_period_end : typing.Optional[dt.datetime]
            End of the invoice's billing period, exclusive: for a period through 31 January send 2026-02-01T00:00:00Z. Send with billing_period_start.

        billing_period_start : typing.Optional[dt.datetime]
            Start of the invoice's billing period, inclusive. Send with billing_period_end.

        currency : typing.Optional[str]
            ISO 4217 currency code; required unless tax_calculation_id is set

        customer_id : typing.Optional[str]
            Existing customer to bill. On the tax_calculation_id path, leave empty to mint a guest customer from the calculation's buyer.

        description : typing.Optional[str]
            Invoice description or memo

        issue_date : typing.Optional[dt.datetime]
            Date to issue the invoice

        line_items : typing.Optional[typing.Sequence[CreateInvoiceLineItemRequest]]
            Line items to include on the invoice

        merchant_id : typing.Optional[str]
            Existing sub-merchant the invoice is issued for; you remain the seller of record. Create the merchant before referencing it here. Optional alongside tax_calculation_id, where it must match the merchant the calculation was made for. Requires the merchants entitlement

        payment : typing.Optional[InvoicePaymentRequest]
            Record the customer's already-settled payment and mark the invoice paid in the same call; requires tax_calculation_id

        purchase_order_number : typing.Optional[str]
            Purchase order number

        status : typing.Optional[CreateInvoiceRequestStatus]
            Initial invoice status. Defaults to draft. Setting issued releases the invoice for issuance, which completes asynchronously: the response returns the invoice in processing, and it settles to issued shortly after — poll the Get Invoice endpoint to observe the final status. paid is only valid on the tax_calculation_id path and must be sent together with a payment.

        tax_calculation_id : typing.Optional[str]
            Id of a persisted tax calculation; its stored line items, tax amounts, and buyer become the invoice, which is issued synchronously with no recalculation. Mutually exclusive with line_items (the calculation supplies them). Leave status unset or set it to issued to issue the invoice; set status to paid together with a payment to also mark it paid.

        idempotency_key : typing.Optional[str]

        request_options : typing.Optional[RequestOptions]
            Request-specific configuration.

        Returns
        -------
        InvoiceResponse
            Success

        Examples
        --------
        import asyncio

        from alguna import AsyncAlguna

        client = AsyncAlguna(
            api_version="YOUR_API_VERSION",
            api_key="YOUR_API_KEY",
        )


        async def main() -> None:
            await client.invoices.create()


        asyncio.run(main())
        """
        _response = await self._raw_client.create(
            billing_period_end=billing_period_end,
            billing_period_start=billing_period_start,
            currency=currency,
            customer_id=customer_id,
            description=description,
            issue_date=issue_date,
            line_items=line_items,
            merchant_id=merchant_id,
            payment=payment,
            purchase_order_number=purchase_order_number,
            status=status,
            tax_calculation_id=tax_calculation_id,
            idempotency_key=idempotency_key,
            request_options=request_options,
        )
        return _response.data

